from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class BeatOrBombStoCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.initial_sum = None
        self.opponent_played_sum = 0
        self.my_played_sum = 0

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        my_remaining_cards = message.message[0].data[0]
        my_current_score = message.message[0].data[1]
        opponent_current_score = message.message[0].data[2]
        my_prev_decision = message.message[0].data[3]
        opponent_prev_decision = message.message[0].data[4]

        if self.initial_sum is None:
            self.initial_sum = sum(self.card_value(card) for card in my_remaining_cards)

        if my_prev_decision is not None:
            prev_card = my_prev_decision[0]
            self.my_played_sum += self.card_value(prev_card)

        if opponent_prev_decision is not None:
            prev_opponent_card = opponent_prev_decision[0]
            self.opponent_played_sum += self.card_value(prev_opponent_card)

        R = self.initial_sum - self.opponent_played_sum
        m = len(my_remaining_cards)
        card_options = []

        for card in my_remaining_cards:
            X = self.card_value(card)
            min_Y = max(1, R - (m-1)*13)
            max_Y = min(13, R - (m-1)*1)
            possible_Y_count = max_Y - min_Y + 1
            if possible_Y_count <= 0:
                continue

            if X >= max_Y:
                compete_gain = X
                compete_opp_gain = 0
            else:
                num_Y_less_eq_X = max(0, X - min_Y + 1)
                prob = num_Y_less_eq_X / possible_Y_count
                compete_gain = X * prob
                count_Y_gt_X = max_Y - X
                if count_Y_gt_X <= 0:
                    compete_opp_gain = 0
                else:
                    avg_Y_gt_X = (X + 1 + max_Y) / 2
                    sum_X_plus_Y = (X + avg_Y_gt_X) * count_Y_gt_X
                    compete_opp_gain = sum_X_plus_Y / possible_Y_count

            avg_Y_giveup = (min_Y + max_Y) / 2
            giveup_opp_gain = avg_Y_giveup

            net_compete = compete_gain - compete_opp_gain
            net_giveup = -giveup_opp_gain

            if net_compete > net_giveup:
                option = 'compete'
                net = net_compete
            else:
                option = 'give up'
                net = net_giveup
            card_options.append( (card, option, net, X) )

        if not card_options:
            chosen_move = [my_remaining_cards[0], 'compete']
        else:
            card_options.sort(key=lambda x: (-x[2], -x[3]))
            chosen_move = [card_options[0][0], card_options[0][1]]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_move, type='custom')]
        )

    def card_value(self, card: str) -> int:
        if card == 'A':
            return 1
        elif card == 'J':
            return 11
        elif card == 'Q':
            return 12
        elif card == 'K':
            return 13
        elif card == '10':
            return 10
        else:
            return int(card)

