        self.strategy_type = StrategyType.Custom
        self.my_played_sum = 0
        self.opponent_played_sum = 0
        self.my_played_cards = []
        self.opponent_played_cards = []

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        my_remaining_cards = message.message[0].data[0]
        my_current_score = message.message[0].data[1]
        opponent_current_score = message.message[0].data[2]
        my_prev_decision = message.message[0].data[3]
        opponent_prev_decision = message.message[0].data[4]

        # Update played sums based on previous decisions
        if my_prev_decision is not None:
            prev_card, prev_action = my_prev_decision
            if prev_card not in self.my_played_cards:
                self.my_played_cards.append(prev_card)
                self.my_played_sum += self.card_value(prev_card)

        if opponent_prev_decision is not None:
            opp_prev_card, opp_prev_action = opponent_prev_decision
            if opp_prev_card not in self.opponent_played_cards:
                self.opponent_played_cards.append(opp_prev_card)
                self.opponent_played_sum += self.card_value(opp_prev_card)

        sum_current_my_remaining = sum(self.card_value(c) for c in my_remaining_cards)
        n_remaining = len(my_remaining_cards)
        opponent_remaining_sum = sum_current_my_remaining + self.my_played_sum - self.opponent_played_sum

        best_card = None
        best_operation = None
        best_gain = -float('inf')

        for card in my_remaining_cards:
            C_val = self.card_value(card)
            if n_remaining == 0:
                D_max = D_min = 0
            else:
                D_max = min(opponent_remaining_sum - (n_remaining -1)*1, 13)
                D_min = max(opponent_remaining_sum - (n_remaining -1)*13, 1)

            if D_max <= C_val:
                compete_gain = C_val
            else:
                if D_min > C_val:
                    compete_gain = 0
                else:
                    possible_values = C_val - D_min + 1
                    total_values = D_max - D_min + 1
                    prob = possible_values / total_values if total_values !=0 else 0
                    compete_gain = prob * C_val

            avg_opp = opponent_remaining_sum / n_remaining if n_remaining !=0 else 0

            if compete_gain > avg_opp:
                action = 'compete'
                current_gain = compete_gain
            else:
                action = 'give up'
                current_gain = 0

            if (current_gain > best_gain or 
                (current_gain == best_gain and C_val > self.card_value(best_card))):
                best_gain = current_gain
                best_card = card
                best_operation = action

        if best_card is None and my_remaining_cards:
            best_card = my_remaining_cards[0]
            best_operation = 'compete'

        chosen_move = [best_card, best_operation] if best_card else None
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_move, type='custom')]
        )

    def card_value(self, card):
        if card == 'A':
            return 1
        elif card == 'J':
            return 11
        elif card == 'Q':
            return 12
        elif card == 'K':
            return 13
        elif card == '10':
            return 10
        else:
            return int(card)

